function getViewTransforms(style, back) {
  switch (style) {
    case 'slide':
      return {
        out: `translateX(${back ? '10%' : '-10%'})`,
        in: `translateX(${back ? '-10%' : '10%'})`
      };
    case 'zoom':
      return {
        out: `scale(${back ? '1.1' : '0.9'})`,
        in: `scale(${back ? '0.9' : '1.1'})`
      };
    case 'flip':
      return {
        out: `rotateY(${back ? '90deg' : '-90deg'})`,
        in: `rotateY(${back ? '-90deg' : '90deg'})`
      };
    case 'fade':
    default:
      return {
        out: 'scale(1)',
        in: 'scale(1)' // Fallback
      };
  }
}
